display.text:
# Basic NixOS configuration
{ config, pkgs, lib, ... }:

{
  imports =
    [
      # Results of the hardware scan (disk, CPU, etc.)
      ./hardware-configuration.nix
    ];

  # Use the systemd-boot EFI boot loader.
  boot.loader.systemd-boot.enable = true;
  boot.loader.efi.canTouchEfiVariables = true;

  networking.hostName = "nixos";
  # Enables networking via NetworkManager.
  networking.networkmanager.enable = true;

  # Your time zone.
  time.timeZone = "Asia/Novosibirsk";

  # Russian locale everywhere.
  i18n.defaultLocale = "ru_RU.UTF-8";
  i18n.extraLocaleSettings = {
    LC_ADDRESS = "ru_RU.UTF-8";
    LC_IDENTIFICATION = "ru_RU.UTF-8";
    LC_MEASUREMENT = "ru_RU.UTF-8";
    LC_MONETARY = "ru_RU.UTF-8";
    LC_NAME = "ru_RU.UTF-8";
    LC_NUMERIC = "ru_RU.UTF-8";
    LC_PAPER = "ru_RU.UTF-8";
    LC_TELEPHONE = "ru_RU.UTF-8";
    LC_TIME = "ru_RU.UTF-8";
  };

  # ---- Keyboard: US + RU layouts, switch with Shift+Alt ----
  services.xserver.xkb = {
    layout = "us,ru";
    options = "grp:shift_alt_toggle";
  };

  # GNOME manages layouts itself on Wayland, so also hand it explicit input
  # sources via dconf so Shift+Alt works there too.
  # Блокируем ключи locks — они не смогут быть изменены через gsettings.
  programs.dconf = {
    enable = true;
    profiles.user.databases = [
      {
        settings = with lib.gvariant; {
          "org/gnome/desktop/input-sources" = {
            sources = [
              (mkTuple [ "xkb" "us" ])
              (mkTuple [ "xkb" "ru" ])
            ];
            xkb-options = [ "grp:shift_alt_toggle" ];
          };
        };
        # Блокируем изменение этих ключей пользователем
        locks = [
          "/org/gnome/desktop/input-sources/sources"
          "/org/gnome/desktop/input-sources/xkb-options"
        ];
      }
    ];
  };

  # GNOME desktop environment.
  services.displayManager.gdm.enable = true;
  services.desktopManager.gnome.enable = true;

  # Printing (CUPS).
  services.printing.enable = true;

  # Sound via PipeWire.
  services.pulseaudio.enable = false;
  security.rtkit.enable = true;
  services.pipewire = {
    enable = true;
    alsa.enable = true;
    alsa.support32Bit = true;
    pulse.enable = true;
  };

  # Your user account.
  users.users."kasiro" = {
    isNormalUser = true;
    description = "kasiro";
    extraGroups = [ "networkmanager" "wheel" ];
  };

  programs.firefox.enable = true;

  # Allow running dynamically linked executables (e.g. the uv_build build
  # backend) intended for generic Linux environments.
  programs.nix-ld.enable = true;

  # doas instead of sudo, no password for wheel.
  # keepenv keeps NIX_PATH/HOME so `doas nixos-rebuild` finds the nixpkgs channel.
  security.doas.enable = true;
  security.doas.extraConfig = ''
    permit nopass keepenv :wheel
  '';

  # Garbage collector — чистит старые поколения и кэш.
  # Запускается автоматически раз в неделю.
  nix.gc = {
    automatic = true;
    dates = "weekly";
    options = "--delete-older-than 30d"; # удаляет поколения старше месяца
  };

  # Оптимизация хранилища (дедупликация файлов).
  nix.optimise.automatic = true;

  # System-wide installed packages.
  environment.systemPackages = with pkgs; [
    git
    micro
    nodejs
    opencode # AI coding assistant for the terminal (this very tool)
    python3
    uv # fast Python package manager
    wl-clipboard # clipboard utilities for Wayland (wl-copy/wl-paste)
  ];

  system.stateVersion = "26.11";
}

