display.text:
# Kasiro user-specific configuration
{ config, pkgs, lib, ... }:

{
  # User account
  users.users.kasiro = {
    isNormalUser = true;
    description = "kasiro";
    extraGroups = [ "networkmanager" "wheel" ];
  };

  # User packages
  environment.systemPackages = with pkgs; [
    git
    micro
    nodejs
    opencode
    python3
    uv
    wl-clipboard
  ];

  # User dconf settings (GNOME settings, extensions, themes, etc.)
  programs.dconf = {
    enable = true;
    profiles.user.databases = [
      {
        settings = with lib.gvariant; {
          # GNOME input sources (keyboard layouts)
          "org/gnome/desktop/input-sources" = {
            sources = [
              (mkTuple [ "xkb" "us" ])
              (mkTuple [ "xkb" "ru" ])
            ];
            xkb-options = [ "grp:shift_alt_toggle" ];
          };

          # Add your GNOME settings here:
          # "org/gnome/desktop/interface" = {
          #   color-scheme = "prefer-dark";
          # };
          # "org/gnome/shell" = {
          #   enabled-extensions = [ "user-theme@gnome-shell-extensions.gcampax.github.com" ];
          # };
        };

        # Lock keys to prevent user changes via gsettings
        locks = [
          "/org/gnome/desktop/input-sources/sources"
          "/org/gnome/desktop/input-sources/xkb-options"
        ];
      }
    ];
  };
}

